    started = time.monotonic()
    proc = run_cmd(["go", "mod", "download"], cwd=worktree, env=env, timeout=600)
    result = {
        "ran": True,
        "ok": proc.returncode == 0,
        "returncode": proc.returncode,
        "seconds": round(time.monotonic() - started, 3),
    }
    if proc.returncode != 0:
        raise RuntimeError(
